async ({ npm: { audit, run }, shell: { execFile }, delivery: { format } }) => {
  const a = await audit();
  const q = await run("quality:audit", [], { maxLines: 40, truncate: "tail" } as any);
  const p = await execFile("npm", ["pack", "--dry-run", "--json"], { maxBytes: 2_000_000 });
  const f = await format({ checkOnly: true });
  let files: string[] = [], size: any;
  try { const j = JSON.parse(p.stdout)[0]; files = j.files.map((x: any) => x.path); size = { size: j.size, unpacked: j.unpackedSize, count: j.entryCount }; } catch (e) { files = [String(p.stdout).slice(0, 2000)]; }
  const dirs: Record<string, number> = {};
  for (const x of files) { const d = x.includes("/") ? x.split("/").slice(0, 2).join("/") : x; dirs[d] = (dirs[d] ?? 0) + 1; }
  return { audit: { code: a.code, out: String(a.stdout).slice(-600) }, quality: { code: q.code, out: String(q.stdout).slice(-1500) }, pack: { code: p.code, size, dirs }, f };
}
